// Drops bots (hidden honeypot field filled) and incomplete submissions,
// then builds the membership notification email for the HNA president.
const b = $input.first().json.body || {};
const clean = (v, max = 500) => String(v ?? '').trim().slice(0, max);
const esc = (v) => clean(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const okEmail = (e) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e);

if (clean(b.website)) return [];
const m = {
  name: clean(b.name, 120), phone: clean(b.phone, 40), email: clean(b.email, 160), address: clean(b.address, 240),
  name2: clean(b.name2, 120), phone2: clean(b.phone2, 40), email2: clean(b.email2, 160),
  kids: clean(b.kids, 4) || '0',
};
if (!m.name || !m.address || !(m.phone || m.email)) return [];
if (m.email && !okEmail(m.email)) m.email = '';
if (m.email2 && !okEmail(m.email2)) m.email2 = '';
const hasAdult2 = !!(m.name2 || m.phone2 || m.email2);

const received = new Date().toLocaleString('en-US', { timeZone: 'America/Chicago', dateStyle: 'medium', timeStyle: 'short' });
const tel = (p) => p ? `<a href="tel:${p.replace(/[^0-9+]/g, '')}">${esc(p)}</a>` : '—';
const mail = (e) => e ? `<a href="mailto:${esc(e)}">${esc(e)}</a>` : '—';
const maps = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(m.address);
const row = (k, v) => `<tr><td style="padding:6px 14px 6px 0;color:#6b7d93;white-space:nowrap;vertical-align:top">${k}</td><td style="padding:6px 0;color:#1B2D44">${v}</td></tr>`;
const sec = (t) => `<tr><td colspan="2" style="padding:14px 0 4px;color:#C9A043;font-size:11px;font-weight:bold;letter-spacing:.12em;text-transform:uppercase">${t}</td></tr>`;

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px">
<div style="background:#1B2D44;color:#fff;padding:14px 18px;border-bottom:4px solid #C9A043"><strong>New 2027 HNA Membership</strong></div>
<div style="padding:16px 18px;border:1px solid #e3e3e3;border-top:0">
<p style="margin:0 0 6px">${esc(m.name)} signed up to join The Highlands Neighborhood Association for 2027.</p>
<table style="border-collapse:collapse;font-size:14px">
${sec('Primary member')}
${row('Name', esc(m.name))}
${row('Phone', tel(m.phone))}
${row('Email', mail(m.email))}
${row('Address', `<a href="${maps}">${esc(m.address)}</a>`)}
${hasAdult2 ? sec('Additional adult') + row('Name', esc(m.name2) || '—') + row('Phone', tel(m.phone2)) + row('Email', mail(m.email2)) : ''}
${sec('Household')}
${row('Children under 18', esc(m.kids))}
${row('Received', received)}
</table>
<p style="margin:14px 0 0;color:#6b7d93;font-size:12px">Source: HNA 2027 membership page (QR). Reply to this email to respond to the member directly.</p>
</div></div>`;

return [{ json: { ...m, received, subject: `New HNA Membership: ${m.name} (${m.address})`, html } }];
